def rows(p):
 with p.open()as f:return list(csv.DictReader(f))
def number(v,fmt='.6f'):return format(float(v),fmt)if v not in [None,'']else 'N/A'
def table(data,columns):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(label)+'</th>'for key,label in columns)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(r[key]))+'</td>'for key,label in columns)+'</tr>'for r in data)+'</tbody></table></div>'
def main():
 out=ROOT/OUT;report=ROOT/REPORT;assert not(out/'freeze.json').exists()
 result=json.loads((report/'summary.json').read_text());budget=json.loads((report/'budget/summary.json').read_text());comparison=json.loads((report/'matched_comparison.json').read_text());build=json.loads((report/'build_validation.json').read_text());positive=json.loads((report/'positivity_diagnostic_audit.json').read_text());assert all(v['all_checks_passed']for v in [result,budget,comparison,build,positive])
 manifest=json.loads((out/'run_manifest.json').read_text());admission={};extent=rows(report/'matched_extent_changes.csv');support=rows(report/'matched_label_support.csv');regions=rows(report/'fixed_principal_region_changes.csv');groups=rows(report/'water_group_cell_summary.csv');oldgroups=rows(ROOT/PRIOR_REPORT/'water_group_cell_summary.csv')
 for run in manifest['runs']:
  case=run['case_id'];x=result['cases'][case];b=budget['case_summaries'][case];folder=ROOT/run['folder'];previous=ROOT/run['previous_e2e_folder']
  with Dataset(folder/'sfincs_his.nc')as d,Dataset(previous/'sfincs_his.nc')as old:boundary=float(d['status'][0])==0 and np.array_equal(chartostring(d['crosssection_name'][:]),chartostring(old['crosssection_name'][:]))
  gates={'completion':True,'identity':True,'geometry':x['fixed_geometry_identical']and x['boundary_closure_audit']['geometry_admission_gate'],'fields':x['required_uncensored_fields_finite'],'time':True,'clock_alignment':True,'boundary':bool(boundary),'rain':abs(b['actual_applied_rain_m3']-b['continuous_encoded_input_rain_m3'])<=1e-6*max(1,b['continuous_encoded_input_rain_m3']),'budget':b['budget_endpoint_pass']and b['budget_prefix_pass'],'censoring':x['censoring_proven']}
  masks=readnp(out/(case+'_candidate_reference.npz'));preview=event_admission(gates,masks);admission[case]={'required_gates':gates,'frozen_policy_function_preview':preview,'candidate_partial_numerical_reference':preview['technical_reference'],'strict_positivity_verified':positive['cases'][case]['strict_positivity_verified'],'formal_registry_changed':False,'training_release':False,'physical_event_accuracy_verified':False,'propagated_error_bounded':False,'scope':'two completed v2 open controls; early v1 attempt excluded; same assumed-barrier and interval rules; no historic relabeling'}
 dump(report/'reference_admission_assessment.json',admission);solver=json.loads((out/'solver_binding.json').read_text())
 dump(out/'qualification.json',{'solver_image_id':solver['image_id'],'patch_sha256':solver['patch_sha256'],'two_control_end_to_end_qualified':True,'strict_positivity_verified':all(p['strict_positivity_verified']for p in positive['cases'].values()),'actual_clock_budget_output_pass':True,'declared_boundary_closures_satisfied':result['all_declared_boundary_closures_satisfied'],'candidate_partial_references':{c:a['candidate_partial_numerical_reference']for c,a in admission.items()},'retained_interrupted_v1_attempts':1,'formal_registry_changed':False,'formal_reference_release':False,'training':0,'batch_58':0,'physical_accuracy_verified':False,'grid_convergence_verified':False})
 data=[];details=[];supports=[];diagnostics=[]
 for case in CASES:
  x=result['cases'][case];b=budget['case_summaries'][case];c=comparison['cases'][case];p=positive['cases'][case];e=next(r for r in extent if r['case']==case and r['scope']=='Three wards'and r['support']=='all_eligible_ground'and float(r['threshold_m'])==.1);s=next(r for r in support if r['case']==case and r['scope']=='Three wards');rr=[r for r in regions if r['case']==case and float(r['threshold_m'])==.1]
  data.append({'case':'干组'if case==CASES[0]else'降雨组','negative':f"{c['old_ever_negative_cells']} → {c['new_ever_negative_cells']}",'minimum':f"{c['old_minimum_signed_volume_m3']:.6f} → {c['new_minimum_signed_volume_m3']:.6f}",'closed':f"{c['old_closed_boundary_faces_with_flux']} → {c['new_closed_boundary_faces_with_flux']}",'area':f"{e['old_certain_wet_km2']} → {e['new_certain_wet_km2']}",'iou':number(e['certain_extent_iou']),'budget':number(c['old_max_abs_step_budget_residual_m3'],'.9g')+' → '+number(b['max_abs_step_budget_residual_m3'],'.9g')})
  details.append(f"{case}：三区>0.10 m确定积水支持变化 {number(e['certain_wet_area_change_pct'],'.4f')}%，IoU {number(e['certain_extent_iou'])}，区间保守范围 [{number(e['interval_extent_iou_lower'])}, {number(e['interval_extent_iou_upper'])}]。固定旧前10主要峰值连片，仍越阈且连通的最大保留支持最少 {min(float(r['largest_retained_connected_support_pct'])for r in rr):.3f}%。")
  details.append(f"{case}：前后深度区间之间的最小必要绝对变化最大 {number(e['max_minimum_required_abs_depth_change_m'])} m；可确认变化>0.01 m的地面 {float(e['ground_minimum_required_change_gt_0_01m_km2'])*1e6:.2f} m²，>0.10 m为 {float(e['ground_minimum_required_change_gt_0_1m_km2'])*1e6:.2f} m²。")
  supports.append({'case':case,'admitted':s['old_admitted_mask_km2']+' → '+s['new_admitted_mask_km2'],'exact':s['old_exact_label_mask_km2']+' → '+s['new_exact_label_mask_km2'],'interval':s['old_interval_label_mask_km2']+' → '+s['new_interval_label_mask_km2'],'quarantine':s['old_quarantine_mask_km2']+' → '+s['new_quarantine_mask_km2'],'state':admission[case]['frozen_policy_function_preview']['state']})
  diagnostics.append(f"{case}：{p['actual_steps']}个实际步中，{p['steps_with_limiting']}步触发限制，累计{p['limited_face_step_observations']}次格面限制；首次端点 {number(p['first_limited_actual_endpoint_s'])} s。原有负值事件下穿 {c['old_down_crossings']} → {c['new_down_crossings']} 次，结束仍负 {c['old_final_negative_cells']} → {c['new_final_negative_cells']} 格。实际入雨 {b['actual_applied_rain_m3']:.6f} m³，累计边界流出 {c['old_boundary_out_m3']:.6f} → {c['new_boundary_out_m3']:.6f} m³、流入 {c['old_boundary_in_m3']:.6f} → {c['new_boundary_in_m3']:.6f} m³，最终有符号储量 {c['old_final_signed_storage_m3']:.6f} → {c['new_final_signed_storage_m3']:.6f} m³。")
 columns=[('case','组别'),('negative','全域曾负单元'),('minimum','最小体积 m³'),('closed','违规关闭面'),('area','三区积水 km²'),('iou','确定范围IoU'),('budget','最大累计预算残差 m³')];supportcols=[('case','组别'),('admitted','三区候选支持 km²'),('exact','精确标签支持 km²'),('interval','区间标签支持 km²'),('quarantine','隔离支持 km²'),('state','原政策预览')]
 text='''# 守恒正性限制：两组全域10 m对照\n\n只完成既有干控制和降雨控制的v2重放；科学输入、雨型水位、几何、原数值参数、线程、父事件谱系和划分保持不变。对照基线为已修复关闭边界的版本。未训练、未执行58个情景。Framelog MILI-D-20261015-014。\n\n## 实现与回归\n\n在所有动量／边界通量已得到、连续方程与同一步预算捕获之前，按每个内部供水单元的原有有符号储量加本步原生单精度非负入雨计算支出上限，不预支同时流入。每个共享格面只按供水方系数缩放一次；相邻格使用同一交换，外部给定水位流入不受内部储量限制。速度及边界平均流量记忆同步缩放，原关闭面修复保持。原生有符号储量从不裁零，不增加雨量或虚构源汇。\n\n留出64倍单精度机器精度的相对运算余量，并把受限流量向零舍入，覆盖非正规数。余量留在供水格，未加水或删水。与未限制的提议流量之差仅是诊断量，不是物理损失、措施效益或预算源汇。不给本步流入即时支付能力是一项保守的离散选择；峰值及连片影响必须由本轮对照检验。\n\n205组生产限制器已知／随机数组更新覆盖干格、多向支出、正雨量、边界流入与极小储量，正性及独立算术／守恒检查通过；串行并行相同，未触发时原流量不变。Fortran NetCDF链接及加载检查通过。\n\n初版虽通过普通尺度测试，补充非正规数回归仍复现向上舍入导致极微小负值。已停止一份早期干组尝试并保留源码、镜像、输入和输出；初版降雨未启动。该尝试不计入完成控制、不作标签。完整有效重放仅为修订版两组；没有隐去失败或放宽阈值。\n\n## 实际结果\n\n|组别|全域曾负单元 前→后|最小体积 m³ 前→后|违规关闭面 前→后|三区>0.10m支持 km² 前→后|确定范围IoU|最大累计预算残差 m³|\n|---|---:|---:|---:|---:|---:|---:|\n'''
 text+=''.join('|'+'|'.join(str(r[k])for k,l in columns)+'|\n'for r in data)+'\n'+'\n'.join('- '+d for d in diagnostics)
 text+='\n\n边界累计流入与流出均明显改变，净储量变化则小得多；因此峰值范围接近不等于边界流量过程稳定，也不能把累计双向交换减少直接解释为真实河流流量改善。逐步最小体积和逐格全事件最小体积均单独检查，严格非负检查不只使用原−0.001 m³事件阈值。限制器每一步的真实时刻、步长和控制组账本一一对应。旧结果不覆盖，限制后的真实通量直接用于原预算，未给预算增加抵消项。所有578个关闭接收边界面仍按完整逐步历史核验；内部关闭面事件接口保留。\n\n## 三区主要积水区\n\n'+'\n'.join('- '+d for d in details)
 text+='''\n\n峰值平均水深上下界在同一原始0.50 m开敞地面分别重建，0.05/0.10/0.30/0.50 m及各区、跨区贡献范围均保留。全地面与双方均通过单元筛查的支持分别比较。下界跳变不自动视为真实深度差；另报区间之间可确认的变化及面积。旧主要峰值连片固定后比较，避免重新排序掩盖损失。它们不是同时水面或动态排水路线，0.10 m也不是安全标准。本轮未重做5 m加密，不能据此证明网格收敛或现实洪水准确性。\n\n## 标签支持与准入\n\n'''
 for r in supports:text+=f"- {r['case']}：三区候选支持 {r['admitted']} km²，精确标签支持 {r['exact']} km²，区间标签支持 {r['interval']} km²，隔离支持 {r['quarantine']} km²；原政策预览 {r['state']}。\n"
 text+='''\n干组大部分可用支持仍是浅水区间，不是精确零水深，应保留区间监督和评价。仍沿用原10项事件门槛、在线负格、假设障碍接触和浅水／宽区间规则，未扩大或收缩阈值以放行。零负值不会自动消除其他隔离原因。原状态名含snapshot，本轮实际使用逐步证据；未改函数名称。候选支持不是独立观测真值，默认注册表和加载器继续关闭，未放行训练或情景库。此前的几何失败与负体积记录按原版本保留，不回填成新真值。\n\n本次配置只覆盖已审核的非负降雨和给定水位地表过程；带入渗、泵站、负源汇或其他主动措施需另行扩展和核验。下一步应依据这两组的对照及剩余障碍／区间支持，决定是否进行有限的网格与复杂暴雨验证，再决定正式建库；不从两组合成控制推导全情景、真实事件或完整河道动力学已验证。\n\n## 复核文件\n\n- positivity_diagnostic_audit.json：每个实际步的限制动作与严格非负核验。\n- budget/summary.json：原门槛下同一步水量、实际时钟及输出对接。\n- matched_comparison.json、matched_extent_changes.csv、fixed_principal_region_changes.csv：范围、区间及固定主要连片。\n- matched_label_support.csv、reference_admission_assessment.json：支持变化及原政策预览。\n- boundary_closure_audit.json：完整关闭边界流量。\n- water_group_cell_summary.csv：分水域组负值核验；无负值时事件表保留表头而无伪造记录。\n- build_validation.json、source_binding.json：生产回归、来源及镜像绑定。\n'''
 (report/'README.md').write_text(text);(report/'source_binding.json').write_bytes((out/'source_binding.json').read_bytes())
 groupdisplay=[{'case':r['case'],'group':r['water_group_code']+' '+r['water_group_name'],'old':next(o['negative_unique_cells']for o in oldgroups if o['case']==r['case']and o['water_group_code']==r['water_group_code']),'new':r['negative_unique_cells']}for r in groups]
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>守恒正性限制 · 两组控制</title><style>body{font:16px/1.8 system-ui,sans-serif;background:#edf2f4;color:#203c48;margin:0}main{max-width:1200px;margin:auto;padding:28px}section{background:white;border:1px solid #dbe5e9;border-radius:12px;padding:24px;margin:20px 0}h1{font-size:30px;line-height:1.4}h2{font-size:22px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:9px;text-align:left;border-bottom:1px solid #e0e7ea}img{width:100%;height:auto}.note{border-left:4px solid #bd8640;padding-left:15px}a{color:#146c81}@media(max-width:650px){main{padding:12px}section{padding:16px}}</style><main><p>Mili · 全域10 m · 三区及跨区贡献范围</p><h1>守恒正性限制：两组匹配对照</h1><p>供水格支出上限、共享格面单次缩放；保持既有关闭边界修复及原科学输入。未裁零储量，未训练、未批跑58情景。</p><section><h2>负体积与水量平衡</h2>__MAIN__<p>严格非负同时核对逐步全域最小值和逐格全事件最小值。预算直接使用限制后通量，没有额外抵消项。</p>__DIAG__</section><section><h2>三区主要积水区</h2>__DETAIL__<img src="whole_domain_positivity_comparison.png" alt="正性限制前后全域峰值水深及差值"><p class="note">峰值支持不代表同时水面或动态排水路线；未重跑5 m加密，不宣称网格收敛。浅水区间与局部深度变化另列。</p></section><section><h2>参考标签支持</h2>__SUPPORT__<p>保持原事件门槛和单元隔离。部分技术参考不等于现实准确性或正式训练准入；默认注册表和加载器继续关闭。</p></section><section><h2>水域组与版本记录</h2>__GROUP__<p>水域组可多重归属；无负值时不伪造触发时刻或事件。初版极小储量回归失败，早期干组尝试已停止并完整保留；初版雨组未启动。完成结果只使用修订版两组。</p></section><section><h2>复核文件</h2><p><a href="README.md">完整说明</a> · <a href="positivity_diagnostic_audit.json">限制动作及严格非负</a> · <a href="budget/summary.json">时钟水量</a> · <a href="matched_extent_changes.csv">三区及各区积水变化</a> · <a href="fixed_principal_region_changes.csv">固定主要连片</a> · <a href="matched_label_support.csv">标签支持变化</a> · <a href="reference_admission_assessment.json">原政策准入预览</a> · <a href="boundary_closure_audit.json">关闭边界</a> · <a href="build_validation.json">生产回归</a> · <a href="source_binding.json">源码镜像绑定</a></p></section></main></html>'''
 page=page.replace('__MAIN__',table(data,columns)).replace('__DETAIL__',''.join('<p>'+html.escape(d)+'</p>'for d in details)).replace('__DIAG__',''.join('<p>'+html.escape(d)+'</p>'for d in diagnostics)).replace('__SUPPORT__',table(supports,supportcols)).replace('__GROUP__',table(groupdisplay,[('case','组别'),('group','水域组'),('old','旧曾负格'),('new','新曾负格')]))
 (report/'review.html').write_text(page)
 p=ROOT/'docs/AnaSOP.md';backup=report/'previous-AnaSOP.md'
 if not backup.exists():backup.write_bytes(p.read_bytes())
 before=backup.read_text();parts=re.split(r'(?=^## [1-8]\. )',before,flags=re.M)
 counts=' and '.join(f"{comparison['cases'][c]['old_ever_negative_cells']} to {comparison['cases'][c]['new_ever_negative_cells']} in the {'dry'if c==CASES[0]else'rainy'} control"for c in CASES)
 add={4:f'''A subsequent conservative positivity version is evaluated on the same original eligible ground. The matched controls change ever-negative cell counts from {counts}. Reintegrate each version's peak-depth bounds and reapply the unchanged negative, assumed-barrier and shallow-interval masks. Limiter receipts are numerical response-quality diagnostics, not surrogate predictors. Keep the earlier interrupted implementation attempt out of reference use and preserve its source and failure evidence.''',6:'''Apply one shared native-face flux reduction according to the interior donor's prior signed storage plus native nonnegative rainfall, without pre-spending simultaneous inflow. Scale velocity and boundary-flow memory consistently, retain a floating-point reserve and round restricted flux toward zero, including subnormal values. Do not clip storage or introduce balancing sources. The same limited flux enters both neighboring continuity updates and the original budget. This conservative donor choice can affect propagation and is evaluated through whole-domain paired peak bounds, fixed principal accumulation regions, same-step budgets and strict every-step nonnegativity; report paired gross boundary exchanges separately from net storage because similar peak extents do not validate flow histories. Two synthetic controls do not establish grid convergence, real-event accuracy or dynamic-route validity.''',7:'''The authorized conservative positivity implementation and exactly two completed revised-control replays are assessed separately from an earlier stopped dry attempt whose subnormal regression failed. Preserve all versions and exclude the stopped attempt from labels. Evaluate strict nonnegativity beyond the historical negative-event threshold, complete closed-boundary histories, actual clocks and unchanged water-balance gates. Quantify candidate support gains while retaining assumed-barrier and interval exclusions. The historical registry, default loader, training and prospective batch remain closed. Decide subsequent bounded grid and forcing validation from these controls before formal library construction; do not count solver versions as independent parent events.'''}
 for i,part in enumerate(parts):
  if part.startswith('## '):
   n=int(re.match(r'## (\d)',part).group(1))
   if n in add and add[n]not in part:parts[i]=part.rstrip()+'\n\n'+add[n]+'\n\n'
 p.write_text(''.join(parts));original=re.split(r'(?=^## [1-8]\. )',backup.read_text(),flags=re.M);changed={int(re.match(r'## (\d)',a).group(1))for a,b in zip(original,parts)if a!=b};assert changed=={4,6,7};dump(report/'anasop-update.json',{'sections_changed':[4,6,7],'skills':['data-preprocessing','estimation-framework-planning'],'human_record':'MILI-D-20261015-014','prior_sha256':sha(backup),'current_sha256':sha(p),'new_final_variables':0,'new_formulas':0,'other_sections_unchanged':True})
 print(json.dumps({'report':str(report/'review.html'),'candidate_states':{c:a['frozen_policy_function_preview']['state']for c,a in admission.items()}}))
if __name__=='__main__':main()
